        // Initialize OpenSSL
        OpenSSL_add_all_algorithms();
        ERR_load_crypto_strings();

        // 1. Initialize WinHTTP with internal proxy settings
        // Privacy: Force all traffic through the internal bridge to prevent DNS leaks
