            HandleWinHttpError("WinHttpOpen", GetLastError());
            return;
        }

        // 2. Privacy: Disable features that leak identity (Cookies, Auth cache, Redirects)
        DWORD dwDisable = WINHTTP_OPTION_REDIRECT_POLICY_NEVER;
        WinHttpSetOption(hSession, WINHTTP_OPTION_REDIRECT_POLICY, &dwDisable, sizeof(dwDisable));

        DWORD dwProtocols = WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_2 | WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_3;
        WinHttpSetOption(hSession, WINHTTP_OPTION_SECURE_PROTOCOLS, &dwProtocols, sizeof(dwProtocols));
    }

    ~TorV3PrivacyClient() {
