    // --- Secure POST Implementation ---
    std::string SendPostRequest(const std::string& onionUrl, const std::string& jsonData) {
        HINTERNET hConnect = NULL, hRequest = NULL;
        std::string response;
        URL_COMPONENTS urlComp = { 0 };
