Here is the Node.js solution using the **Sharp** library. This implementation addresses the dynamic selection of watermark sizes, smart placement based on image detail, and support for common formats including animated GIFs.

### Implementation Logic:
1.  **Multi-Watermark Selection:** The script iterates through the provided watermark paths and selects the one with a native width closest to the target width (15% of the base image) to ensure the highest visual quality before final scaling.
2.  **Smart Placement:** It analyzes the four corners of the source image by calculating the **Standard Deviation** of pixel values. It selects the corner with the lowest value, representing the area with the least detail or "busyness."
3.  **Transparency & Format Support:** It handles JPEG, PNG, and GIF. For GIFs, the `{ animated: true }` option is used to ensure the watermark is applied across all frames. Transparency is applied by compositing the watermark with a generated alpha mask.

```javascript
const sharp = require('sharp');
const fs = require('fs');

/**
 * Adds a watermark to an image in the corner with the least detail.
 * 
 * @param {string} inputPath - Path to the source image (JPG, PNG, GIF).
 * @param {string[]} watermarkPaths - Array of paths to watermark files of different sizes.
 * @param {string} outputPath - Path to save the result.
 * @param {number} opacity - Transparency level (0.0 to 1.0).
 */
async function addSmartWatermark(inputPath, watermarkPaths, outputPath, opacity = 0.5) {
    try {
        // 1. Load base image metadata
        const base = sharp(inputPath, { animated: true });
        const metadata = await base.metadata();
        const { width: bgW, height: bgH } = metadata;
        const targetLogoWidth = Math.floor(bgW * 0.15);

        // 2. Requirement: Choose the proper watermark size
        let bestWatermarkPath = watermarkPaths[0];
        let minSizeDiff = Infinity;

        for (const path of watermarkPaths) {
            const wmMeta = await sharp(path).metadata();
            const diff = Math.abs(wmMeta.width - targetLogoWidth);
            if (diff < minSizeDiff) {
                minSizeDiff = diff;
                bestWatermarkPath = path;
            }
        }

        // 3. Process the chosen watermark (Resize and apply Transparency)
        const watermarkBuffer = await sharp(bestWatermarkPath)
            .resize({ width: targetLogoWidth })
            .ensureAlpha()
            .composite([{
                input: Buffer.from([255, 255, 255, Math.floor(opacity * 255)]),
                raw: { width: 1, height: 1, channels: 4 },
                blend: 'dest-in',
                tile: true
            }])
            .toBuffer();

        const processedWm = sharp(watermarkBuffer);
        const { width: logoW, height: logoH } = await processedWm.metadata();

        // 4. Analyze corners to find the "quietest" spot
        const margin = Math.floor(bgW * 0.02);
        const regions = {
            'top-left': { left: margin, top: margin, width: logoW, height: logoH },
            'top-right': { left: bgW - logoW - margin, top: margin, width: logoW, height: logoH },
            'bottom-left': { left: margin, top: bgH - logoH - margin, width: logoW, height: logoH },
            'bottom-right': { left: bgW - logoW - margin, top: bgH - logoH - margin, width: logoW, height: logoH }
        };

        let bestCorner = 'top-left';
        let lowestStdDev = Infinity;

        // Use a non-animated clone for stats analysis to save memory
        const analysisBase = sharp(inputPath).grayscale();

        for (const [name, region] of Object.entries(regions)) {
            const stats = await analysisBase
                .clone()
                .extract(region)
                .stats();

            // Lower standard deviation means a flatter, less busy area
            const stdDev = stats.channels[0].stdev;
            if (stdDev < lowestStdDev) {
                lowestStdDev = stdDev;
                bestCorner = name;
            }
        }

        const finalCoords = regions[bestCorner];

        // 5. Composite and Save
        // Sharp handles JPEG, PNG, and GIF (including animated) based on file extension/metadata
        await base
            .composite([{
                input: watermarkBuffer,
                top: finalCoords.top,
                left: finalCoords.left,
                gravity: 'northwest',
                tile: false
            }])
            .toFile(outputPath);

        console.log(`Success: Selected ${bestWatermarkPath}. Placed in ${bestCorner}. Saved to ${outputPath}`);

    } catch (error) {
        console.error("Error processing image:", error);
    }
}

